package dev.veltraph.client.garden.copy;

import dev.veltraph.client.world.BlockPos;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class GardenCopyTest {
    final GardenRegion r=new GardenRegion(12,0,66,0,1,67,0);
    GardenBlueprint blueprint(){return new GardenBlueprint("mask",r,List.of("minecraft:dirt","minecraft:oak_log[axis=x]","minecraft:air","minecraft:stone"),Set.of());}
    static class Reader implements GardenScan.Reader{Object identity=new Object();Map<BlockPos,GardenScan.Cell> cells=new HashMap<>();public Object identity(){return identity;}public GardenScan.Cell read(BlockPos p){return cells.getOrDefault(p,new GardenScan.Cell(false,null,false));}}
    Reader reader(){var q=new Reader();for(int i=0;i<r.cells();i++)q.cells.put(r.at(i),new GardenScan.Cell(true,blueprint().states().get(i),false));return q;}
    @Test void denseSchemaRetainsAirAllPropertiesAndExactBounds(){var b=blueprint();assertEquals(b,GardenBlueprintStore.decode(GardenBlueprintStore.encode(b)));assertEquals(1L,b.histogram().get("minecraft:air"));assertEquals(1L,b.histogram().get("minecraft:oak_log[axis=x]"));assertThrows(IllegalArgumentException.class,()->new GardenBlueprint("x",r,List.of("minecraft:dirt"),Set.of()));}
    @Test void dimensionAwareAllFourTurnsPreserveNonsquareCellBijection(){var b=blueprint();var origin=new BlockPos(3,66,2);for(int turn=0;turn<4;turn++){var points=new HashSet<BlockPos>();var bounds=b.destinationBounds(origin,turn);for(int i=0;i<r.cells();i++)assertTrue(points.add(b.destination(i,origin,turn))&&bounds.contains(b.destination(i,origin,turn)));assertEquals(4,points.size());}assertEquals(new BlockPos(3,66,3),b.destination(1,origin,1));assertEquals(new BlockPos(3,67,2),b.destination(2,origin,1));}
    @Test void source95By287DimensionsRemainUnreduced(){var region=new GardenRegion(2,-100,66,-140,-6,66,146);var b=new GardenBlueprint("original_span",region,Collections.nCopies(region.cells(),"minecraft:air"),Set.of());assertEquals(95,b.source().width());assertEquals(287,b.source().depth());var bounds=b.destinationBounds(new BlockPos(-140,66,-100),1);assertEquals(287,bounds.width());assertEquals(95,bounds.depth());}
    @Test void scanNeverPublishesPartialOrUnknownCells(){var q=reader();var s=new GardenScan("x",r,4,q);s.tick(q,1);assertTrue(s.result().isEmpty());q.cells.remove(r.at(1));s.tick(q,1);assertEquals(GardenScan.Phase.FAILED,s.phase());assertTrue(s.result().isEmpty());}
    @Test void verifyPassRejectsChangedBlockAndBlockEntityPresence(){for(boolean entity:List.of(false,true)){var q=reader();var s=new GardenScan("x",r,4,q);s.tick(q,4);q.cells.put(r.at(0),new GardenScan.Cell(true,entity?"minecraft:dirt":"minecraft:stone",entity));s.tick(q,4);assertEquals(GardenScan.Phase.FAILED,s.phase());assertTrue(s.result().isEmpty());}}
    @Test void scanCoherentResultIncludesProtectedEntityMarkersButNoPayload(){var q=reader();q.cells.put(r.at(1),new GardenScan.Cell(true,"minecraft:chest[facing=north,type=single,waterlogged=false]",true));var s=new GardenScan("x",r,4,q);s.tick(q,8);assertEquals(Set.of(1),s.result().orElseThrow().blockEntities());assertTrue(GardenBlueprintStore.encode(s.result().orElseThrow()).contains("blockEntities"));}
    @Test void worldChangeAndCancelDiscardScanWithoutReadingReplacement(){var q=reader();var s=new GardenScan("x",r,4,q);q.identity=new Object();s.tick(q,1);assertEquals(GardenScan.Phase.FAILED,s.phase());s=new GardenScan("x",r,4,q);s.tick(q,1);s.cancel();assertEquals(GardenScan.Phase.CANCELLED,s.phase());assertTrue(s.result().isEmpty());}
    @Test void strictIntegersMasksNamesAndBudgetsAreBounded(){String json=GardenBlueprintStore.encode(blueprint());assertThrows(IllegalArgumentException.class,()->GardenBlueprintStore.decode(json+"{}"));assertThrows(IllegalArgumentException.class,()->GardenBlueprintStore.decode(json.replace("\"plot\":12","\"plot\":12.5")));assertThrows(IllegalArgumentException.class,()->new GardenScan("../x",r,4,reader()));assertThrows(IllegalArgumentException.class,()->new GardenScan("x",r,3,reader()));assertThrows(IllegalArgumentException.class,()->new GardenRegion(12,-241,66,0,1,70,0));assertThrows(IllegalArgumentException.class,()->new GardenRegion(12,0,66,0,1,130,0));}
    @Test void localStoreRejectsTraversalSymlinkAndNameMismatch(@TempDir Path temp)throws Exception{var store=new GardenBlueprintStore(temp);store.save(blueprint());assertEquals(blueprint(),store.load("mask"));assertThrows(java.io.IOException.class,()->store.load("../mask"));Files.createSymbolicLink(temp.resolve("link.json"),temp.resolve("mask.json"));assertThrows(java.io.IOException.class,()->store.load("link"));Files.writeString(temp.resolve("other.json"),GardenBlueprintStore.encode(blueprint()));assertThrows(java.io.IOException.class,()->store.load("other"));}
    GardenPasteRuntime.Facts f(boolean exact,boolean resource,long time){return new GardenPasteRuntime.Facts(true,exact,!exact,resource,true,true,true,time);}
    @Test void nativeAttemptIsNotItsOwnAckAndRequiresStableDelayedObservedState(){var p=new GardenPasteRuntime();assertEquals(GardenPasteRuntime.Action.PLACE,p.tick(2,f(false,true,1000),250,10000,3));assertEquals(0,p.index());assertEquals(GardenPasteRuntime.Action.WAIT,p.tick(2,f(true,true,1100),250,10000,3));assertEquals(0,p.index());p.tick(2,f(true,true,1300),250,10000,3);assertEquals(0,p.index());p.tick(2,f(true,true,1350),250,10000,3);assertEquals(1,p.index());}
    @Test void materialPauseExplicitResumeRetainsConfirmedCheckpoint(){var p=new GardenPasteRuntime();p.tick(2,f(true,true,1000),250,10000,3);assertEquals(GardenPasteRuntime.Action.PAUSE,p.tick(2,f(false,false,1100),250,10000,3));p.resume();assertEquals(1,p.index());assertEquals(GardenPasteRuntime.Action.PLACE,p.tick(2,f(false,true,5000),250,10000,3));}
    @Test void unknownOccupiedAndUnacknowledgedRetriesStopRatherThanCompleting(){var p=new GardenPasteRuntime();assertEquals(GardenPasteRuntime.Action.FAIL,p.tick(1,new GardenPasteRuntime.Facts(false,false,true,true,true,true,true,1000),250,10000,3));p=new GardenPasteRuntime();assertEquals(GardenPasteRuntime.Action.FAIL,p.tick(1,new GardenPasteRuntime.Facts(true,false,false,true,true,true,true,1000),250,10000,3));p=new GardenPasteRuntime();assertEquals(GardenPasteRuntime.Action.PLACE,p.tick(1,f(false,true,1000),250,10000,1));assertEquals(GardenPasteRuntime.Action.FAIL,p.tick(1,f(false,true,1600),250,10000,1));assertEquals(0,p.index());}
}
